  1	import type { IncomingMessage, ServerResponse } from 'node:http';
  2	import type { Router } from '../router.js';
  3	import type { RepositoryManager } from '../../models/repository/repository.manager.js';
  4	import { NotFoundError } from '../../errors.js';
  5	import { parseJsonBody, sendJson, sendError, isPlainObject } from '../requestUtils.js';
  6	import type { Repository } from '../../models/repository/repository.types.js';
  7	import type { AppConfig, GitCredentialEntry } from '../../config/config.types.js';
  8	import { extractHost } from '../../git/git-credentials.js';
  9	
 10	// ---------------------------------------------------------------------------
 11	// Route registration
 12	// ---------------------------------------------------------------------------
 13	
 14	/**
 15	 * Registers all routes for the `/api/repositories` resource group on the
 16	 * provided `Router` instance. This includes five standard CRUD routes and two
 17	 * credential-management routes that require access to the application
 18	 * configuration.
 19	 *
 20	 * All handlers delegate to the supplied `RepositoryManager` and map results
 21	 * or errors to the appropriate HTTP status codes:
 22	 *
 23	 * | Method | Path                                        | Success | Failure |
 24	 * |--------|---------------------------------------------|---------|---------|
 25	 * | GET    | /api/repositories                           | 200     | —       |
 26	 * | GET    | /api/repositories/:id                       | 200     | 404     |
 27	 * | POST   | /api/repositories                           | 201     | 400     |
 28	 * | PUT    | /api/repositories/:id                       | 200     | 404     |
 29	 * | DELETE | /api/repositories/:id                       | 204     | 404     |
 30	 * | POST   | /api/repositories/:id/refresh-timestamp     | 200     | 404     |
 31	 * | PUT    | /api/repositories/:id/credential            | 200     | 400/404 |
 32	 * | GET    | /api/repositories/:id/credential-options    | 200     | 404     |
 33	 */
 34	export function registerRepositoryRoutes(
 35	    router: Router,
 36	    repoManager: RepositoryManager,
 37	    appConfig: AppConfig,
 38	): void {
 39	    /**
 40	     * Look up a repository by ID.
 41	     *
 42	     * Sends a `404` response and returns `undefined` when the repository
 43	     * cannot be found.
 44	     *
 45	     * @param res          - The outgoing HTTP response (used to send the 404 error).
 46	     * @param repositoryId - The ID of the repository to look up.
 47	     * @returns The matching `Repository` on success, or `undefined` when a 404
 48	     *          has already been written to `res`.
 49	     */
 50	    function resolveRepository(
 51	        res: ServerResponse,
 52	        repositoryId: string,
 53	    ): Repository | undefined {
 54	        const repo = repoManager.getById(repositoryId);
 55	        if (repo === undefined) {
 56	            sendError(res, 404, `Repository with ID "${repositoryId}" not found.`);
 57	            return undefined;
 58	        }
 59	        return repo;
 60	    }
 61	
 62	    // ------------------------------------------------------------------
 63	    // GET /api/repositories — list all
 64	    // ------------------------------------------------------------------
 65	    router.get('/api/repositories', (
 66	        _req: IncomingMessage,
 67	        res: ServerResponse,
 68	        _params: Record<string, string>,
 69	    ): void => {
 70	        const repos = repoManager.list();
 71	        sendJson(res, 200, repos);
 72	    });
 73	
 74	    // ------------------------------------------------------------------
 75	    // GET /api/repositories/:id — get one
 76	    // ------------------------------------------------------------------
 77	    router.get('/api/repositories/:id', (
 78	        _req: IncomingMessage,
 79	        res: ServerResponse,
 80	        params: Record<string, string>,
 81	    ): void => {
 82	        const repo = resolveRepository(res, params['id']);
 83	        if (repo === undefined) return;
 84	        sendJson(res, 200, repo);
 85	    });
 86	
 87	    // ------------------------------------------------------------------
 88	    // POST /api/repositories — create
 89	    // ------------------------------------------------------------------
 90	    router.post('/api/repositories', async (
 91	        req: IncomingMessage,
 92	        res: ServerResponse,
 93	        _params: Record<string, string>,
 94	    ): Promise<void> => {
 95	        let body: unknown;
 96	        try {
 97	            body = await parseJsonBody(req);
 98	        } catch (err) {
 99	            sendError(res, 400, err instanceof Error ? err.message : 'Invalid request body.');
100	            return;

101	        }
102	
103	        if (!isPlainObject(body)) {
104	            sendError(res, 400, 'Request body must be a JSON object.');
105	            return;
106	        }
107	
108	        const { url, name, id } = body as {
109	            url?: unknown;
110	            name?: unknown;
111	            id?: unknown;
112	        };
113	
114	        if (typeof url !== 'string' || url.trim() === '') {
115	            sendError(res, 400, 'Missing required field: url (non-empty string).');
116	            return;
117	        }
118	
119	        const params: { url: string; name?: string; id?: string } = { url: url.trim() };
120	        if (typeof name === 'string') params.name = name;
121	        if (typeof id === 'string') params.id = id;
122	
123	        try {
124	            const repo = repoManager.add(params);
125	            sendJson(res, 201, repo);
126	        } catch (err) {
127	            sendError(res, 400, err instanceof Error ? err.message : 'Could not create repository.');
128	        }
129	    });
130	
131	    // ------------------------------------------------------------------
132	    // PUT /api/repositories/:id — update
133	    // ------------------------------------------------------------------
134	    router.put('/api/repositories/:id', async (
135	        req: IncomingMessage,
136	        res: ServerResponse,
137	        params: Record<string, string>,
138	    ): Promise<void> => {
139	        const id = params['id'];
140	
141	        if (!repoManager.exists(id)) {
142	            sendError(res, 404, `Repository with ID "${id}" not found.`);
143	            return;
144	        }
145	
146	        let body: unknown;
147	        try {
148	            body = await parseJsonBody(req);
149	        } catch (err) {
150	            sendError(res, 400, err instanceof Error ? err.message : 'Invalid request body.');
151	            return;
152	        }
153	
154	        if (!isPlainObject(body)) {
155	            sendError(res, 400, 'Request body must be a JSON object.');
156	            return;
157	        }
158	
159	        const { name } = body as { name?: unknown };
160	
161	        if (typeof name !== 'string' || name.trim() === '') {
162	            sendError(res, 400, 'Missing required field: name (non-empty string).');
163	            return;
164	        }
165	
166	        try {
167	            const updated = repoManager.update(id, { name: name.trim() });
168	            sendJson(res, 200, updated);
169	        } catch (err) {
170	            // update() throws NotFoundError if the ID was removed
171	            // between the exists() check and the update() call (race condition).
172	            if (err instanceof NotFoundError) {
173	                sendError(res, 404, err.message);
174	            } else {
175	                sendError(res, 500, 'Internal server error.');
176	            }
177	        }
178	    });
179	
180	    // ------------------------------------------------------------------
181	    // DELETE /api/repositories/:id — delete
182	    // ------------------------------------------------------------------
183	    router.delete('/api/repositories/:id', (
184	        _req: IncomingMessage,
185	        res: ServerResponse,
186	        params: Record<string, string>,
187	    ): void => {
188	        const id = params['id'];
189	
190	        try {
191	            repoManager.remove(id);
192	        } catch (err) {
193	            if (err instanceof NotFoundError) {
194	                sendError(res, 404, `Repository with ID "${id}" not found.`);
195	            } else {
196	                sendError(res, 500, 'Internal server error.');
197	            }
198	            return;
199	        }
200	
201	        // 204 No Content — no body
202	        res.writeHead(204, {});
203	        res.end('');
204	    });
205	
206	    // ------------------------------------------------------------------
207	    // POST /api/repositories/:id/refresh-timestamp — record manual refresh
208	    //   Writes the current timestamp to LastRefreshedAt for the repository.
209	    //   Called by the GUI whenever the user triggers a manual refresh on
210	    //   the repository detail screen.
211	    // ------------------------------------------------------------------
212	    router.post('/api/repositories/:id/refresh-timestamp', (
213	        _req: IncomingMessage,
214	        res: ServerResponse,
215	        params: Record<string, string>,
216	    ): void => {
217	        const id = params['id'];
218	        try {
219	            const updated = repoManager.touchRefreshTimestamp(id);
220	            sendJson(res, 200, updated);
221	        } catch (err) {
222	            if (err instanceof NotFoundError) {
223	                sendError(res, 404, err.message);
224	            } else {
225	                sendError(res, 500, 'Internal server error.');
226	            }
227	        }
228	    });
229	
230	    // ------------------------------------------------------------------
231	    // PUT /api/repositories/:id/credential — set or clear credential
232	    //
233	    //   Accepts `{ credentialId: string | null }`.
234	    //   - When `credentialId` is a non-empty string, validates that it
235	    //     references an existing entry in `appConfig.gitCredentials`, then
236	    //     calls `RepositoryManager.updateCredential()` to persist the
237	    //     association.
238	    //   - When `credentialId` is `null`, clears the association.
239	    //   Returns the updated `Repository` on success (200).
240	    // ------------------------------------------------------------------
241	    router.put('/api/repositories/:id/credential', async (
242	        req: IncomingMessage,
243	        res: ServerResponse,
244	        params: Record<string, string>,
245	    ): Promise<void> => {
246	        const id = params['id'];
247	
248	        const repo = resolveRepository(res, id);
249	        if (repo === undefined) return;
250	
251	        let body: unknown;
252	        try {
253	            body = await parseJsonBody(req);
254	        } catch (err) {
255	            sendError(res, 400, err instanceof Error ? err.message : 'Invalid request body.');
256	            return;
257	        }
258	
259	        if (!isPlainObject(body)) {
260	            sendError(res, 400, 'Request body must be a JSON object.');
261	            return;
262	        }
263	
264	        const { credentialId } = body as { credentialId?: unknown };
265	
266	        if (credentialId !== null && typeof credentialId !== 'string') {
267	            sendError(res, 400, 'Missing required field: credentialId (string or null).');
268	            return;
269	        }
270	
271	        if (typeof credentialId === 'string') {
272	            // Validate that the referenced credential exists in the config.
273	            const credentials: GitCredentialEntry[] = appConfig.gitCredentials ?? [];
274	            const exists = credentials.some((c) => c.id === credentialId);
275	            if (!exists) {
276	                sendError(
277	                    res,
278	                    400,
279	                    `Credential with ID "${credentialId}" does not exist in the application configuration.`,
280	                );
281	                return;
282	            }
283	        }
284	
285	        try {
286	            const updated = repoManager.updateCredential(id, credentialId as string | null);
287	            sendJson(res, 200, updated);
288	        } catch (err) {
289	            if (err instanceof NotFoundError) {
290	                sendError(res, 404, err.message);
291	            } else {
292	                sendError(res, 500, 'Internal server error.');
293	            }
294	        }
295	    });
296	
297	    // ------------------------------------------------------------------
298	    // GET /api/repositories/:id/credential-options — list matching credentials
299	    //
300	    //   Returns the subset of `appConfig.gitCredentials` whose `host` matches
301	    //   the hostname of the repository's remote URL.  Tokens are masked (replaced
302	    //   with `"***"`) before being sent to the client.
303	    //
304	    //   Response shape:
305	    //     {
306	    //       credentials: GitCredentialEntry[],  // token masked
307	    //       autoSelected?: string               // id of the sole matching credential
308	    //     }
309	    //
310	    //   `autoSelected` is included only when exactly one credential matches the
311	    //   repository's host.
312	    // ------------------------------------------------------------------
313	    router.get('/api/repositories/:id/credential-options', (
314	        _req: IncomingMessage,
315	        res: ServerResponse,
316	        params: Record<string, string>,
317	    ): void => {
318	        const id = params['id'];
319	
320	        const repo = resolveRepository(res, id);
321	        if (repo === undefined) return;
322	
323	        const credentials: GitCredentialEntry[] = appConfig.gitCredentials ?? [];
324	        const repoHost = extractHost(repo.Url);
325	
326	        // Filter to credentials whose host matches the repository's URL host.
327	        // For non-HTTPS URLs (e.g. SSH), repoHost is null and no credentials match.
328	        const matching = repoHost !== null
329	            ? credentials.filter((c) => c.host === repoHost)
330	            : [];
331	
332	        // Mask tokens before sending — never expose raw tokens over the API.
333	        const maskedCredentials: GitCredentialEntry[] = matching.map((c) => ({
334	            ...c,
335	            token: '***',
336	        }));
337	
338	        const responseBody: { credentials: GitCredentialEntry[]; autoSelected?: string } = {
339	            credentials: maskedCredentials,
340	        };
341	
342	        if (matching.length === 1) {
343	            responseBody.autoSelected = matching[0].id;
344	        }
345	
346	        sendJson(res, 200, responseBody);
347	    });
348	}

